"""Сверка цен конкурентов из стратегии заказчика (19.10.2026) с ценами сайтов (съём 20–21.10.2026, data/sites_prices.csv, data/sites_light.csv).
Выход: data/price_reconciliation.csv. Запуск: python3 -I price_reconciliation.py"""
import csv
B = '/home/claude/zabory'
R = [
 ('Мастеровит', 'профнастил «от»', 1550, 'стратегия: «профнастил от 1 550», «профнастил 2 м, 0,5 мм», «монтаж от 1 102»', 1907, 'masterovit.ru/zabory-i-navesy/: «Стандарт» 1,5 м, лист 0,4 мм, с монтажом; на той же странице 1 960 и 2 004 ₽', 'сайт', 'в стратегии позиция и высота не указаны; на сайте 20.10 минимальная цена с монтажом — 1 907 ₽ (1,5 м); 1 550 ₽ могла быть акционной или без монтажа — не проверено'),
 ('ЗаводЗаборов', 'профнастил «от»', 2157, 'стратегия: «профнастил от 2 157»', 1854, 'zavodzaborov.ru: С-8 0,4 мм, 1,5 м, с монтажом; второй сайт 1 376 ₽; в объявлениях Директа «от 742 руб/п.м.»', 'сайт', 'у компании четыре цены «от» на разных площадках (742 / 1 376 / 1 854 / 2 157 ₽); в сравнение взята цена главного сайта с указанной высотой'),
 ('ПрофЗаборы', 'евроштакетник «от»', 2091, 'стратегия: «штакетник от 2 091»', 1399, 'prof-zabory.ru: «от 1 399 ₽»; таблица: 1 м — 1 796 ₽, 1,5 м — 2 450–3 229 ₽; лендинг 1 590 ₽', 'сайт', 'цена 2 091 ₽ в таблице сайта 20.10 не найдена; ближайшая — 1 796 ₽ (1 м) и 2 450 ₽ (1,5 м); высота в стратегии не указана'),
 ('Радуга заборов', 'профнастил', 2200, 'стратегия: «профнастил 2 200»', 850, 'raduga-zaborov.ru: «от 850 ₽» в карточках (1,8–2 м); на странице цен эконом 1,5 м 0,35 мм — 2 100 ₽', 'сайт; в отчёте показаны обе', 'на самом сайте две цены (850 и 2 100 ₽); 2 200 ₽ стратегии ближе к странице цен (+5%)'),
 ('Радуга заборов', 'жалюзи «от»', 3430, 'стратегия: «жалюзи от 3 430»', 2800, 'raduga-zaborov.ru: жалюзи 1,8–2 м «от 2 800 ₽»', 'сайт', 'разница −18%; дата съёма стратегии и высота не указаны'),
 ('КупитьЗабор.ру', 'профнастил «от»', 4500, 'стратегия: «профнастил от 4 500»', 1250, 'moscow.kupitzabor.ru: «от 1 250 руб/м²» (единица — м²); жалюзи хай-тек от 3 350 ₽/п.м.', 'не сравнимо', 'единицы разные: на сайте цена за м², в стратегии единица не указана'),
 ('СтройЗабор', 'профнастил «от»', 999, 'стратегия: «профнастил от 999»', None, 'компании нет в списке брифа; сайт не снимался', 'стратегия', 'не проверено'),
 ('Завод Ворот', 'автоматические ворота «от» / ворота 4 × 2 м', 105000, 'стратегия: «автоворота от 105 000; ворота 4×2 м от 125 560 (особая комплектация)»', None, 'компании нет в списке брифа; медиана ворот 4 м с автоматикой по 6 сайтам — 103 025 ₽ (data/sites_gates.csv)', 'стратегия; рынок — медиана сайтов', '105 000 ₽ стратегии близко к медиане сайтов 103 025 ₽ (+2%)'),
]
out = []
for comp, item, sv, ssrc, site, site_src, taken, why in R:
    out.append({'company': comp, 'item': item, 'strategy_rub': sv, 'strategy_source': ssrc, 'site_rub': site if site else 'нет данных', 'site_source': site_src,
                'diff_site_vs_strategy': ('не сравнимо: разные единицы' if taken == 'не сравнимо' else f'{(site - sv) / sv * 100:+.0f}%' if site else 'не сравнимо'), 'value_taken': taken, 'why': why,
                'date': 'стратегия 19.10.2026; сайты 20–21.10.2026'})
with open(f'{B}/data/price_reconciliation.csv', 'w', encoding='utf-8', newline='') as f:
    w = csv.DictWriter(f, fieldnames=list(out[0].keys())); w.writeheader(); w.writerows(out)
for o in out: print(o['company'], o['item'], o['strategy_rub'], o['site_rub'], o['diff_site_vs_strategy'])
